1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.dto.CheckoutRequest;
4	import com.loja.checkout.dto.CheckoutResponse;
5	import com.loja.checkout.dto.ItemCarrinho;
6	import com.loja.checkout.enums.Cupom;
7	import com.loja.checkout.enums.FormaPagamento;
8	import com.loja.checkout.enums.ModalidadeEntrega;
9	import com.loja.checkout.enums.NivelClube;
10	import com.loja.checkout.exception.CheckoutException;
11	import org.springframework.stereotype.Service;
12	
13	import java.math.BigDecimal;
14	import java.math.RoundingMode;
15	import java.util.HashMap;
16	import java.util.Map;
17	
18	@Service
19	public class CheckoutService {
20	
21	    private static final BigDecimal TAXA_JUROS_MENSAL = new BigDecimal("0.0199");
22	    private static final int PARCELAS_SEM_JUROS = 3;
23	
24	    public CheckoutResponse calcularResumo(CheckoutRequest request) {
25	        validarPedido(request);
26	
27	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(request);
28	        BigDecimal pesoTotal = calcularPesoTotal(request);
29	
30	        validarModalidadeDisponivel(request.getModalidadeEntrega(), pesoTotal);
31	
32	        Cupom cupom = validarCupom(request.getCupom(), subtotalProdutos);
33	        BigDecimal descontoCupom = calcularDescontoCupom(cupom, request, subtotalProdutos);
34	
35	        validarFormaPagamento(request);
36	
37	        BigDecimal frete = calcularFrete(request.getModalidadeEntrega(), request.getNivelClube(), pesoTotal);
38	
39	        if (cupom != null && cupom.getTipo() == Cupom.TipoCupom.FRETE_GRATIS) {
40	            BigDecimal freteOriginal = calcularFreteOriginal(request.getModalidadeEntrega(), pesoTotal);
41	            descontoCupom = freteOriginal;
42	            frete = BigDecimal.ZERO;
43	        }
44	
45	        BigDecimal seguro = calcularSeguro(request.getRegiao(), subtotalProdutos);
46	
47	        BigDecimal totalPedido = subtotalProdutos
48	            .subtract(descontoCupom)
49	            .add(frete)
50	            .add(seguro);
51	
52	        validarFormaPagamentoDisponivel(request.getFormaPagamento(), totalPedido);
53	
54	        BigDecimal ajustePagamento = calcularAjustePagamento(request.getFormaPagamento(), totalPedido);
55	        BigDecimal totalFinal = totalPedido.add(ajustePagamento);
56	
57	        int parcelas = request.getParcelas() != null ? request.getParcelas() : 1;
58	        BigDecimal valorParcela = calcularValorParcela(request.getFormaPagamento(), totalFinal, parcelas);
59	
60	        if (request.getFormaPagamento() == FormaPagamento.CARTAO && parcelas > PARCELAS_SEM_JUROS) {
61	            totalFinal = valorParcela.multiply(new BigDecimal(parcelas));
62	            ajustePagamento = totalFinal.subtract(totalPedido);
63	        }
64	
65	        BigDecimal creditoProximaCompra = calcularCredito(request.getNivelClube(), subtotalProdutos);
66	        boolean brinde = verificarBrinde(request.getNivelClube(), subtotalProdutos);
67	
68	        CheckoutResponse response = new CheckoutResponse();
69	        response.setSubtotalProdutos(subtotalProdutos);
70	        response.setDescontoCupom(descontoCupom);
71	        response.setFrete(frete);
72	        response.setPrazoEntregaDias(request.getModalidadeEntrega().getPrazoEntregaDias());
73	        response.setSeguro(seguro);
74	        response.setAjustePagamento(ajustePagamento);
75	        response.setTotalFinal(totalFinal);
76	        response.setParcelas(parcelas);
77	        response.setValorParcela(valorParcela);
78	        response.setCreditoProximaCompra(creditoProximaCompra);
79	        response.setBrinde(brinde);
80	
81	        return response;
82	    }
83	
84	    private void validarPedido(CheckoutRequest request) {
85	        if (request.getItens() == null || request.getItens().isEmpty()) {
86	            throw new CheckoutException("PEDIDO_INVALIDO");
87	        }
88	
89	        for (ItemCarrinho item : request.getItens()) {
90	            if (item.getPrecoUnitario() == null || item.getPrecoUnitario().compareTo(BigDecimal.ZERO) <= 0 ||
91	                item.getQuantidade() == null || item.getQuantidade() <= 0 ||
92	                item.getPesoKg() == null || item.getPesoKg().compareTo(BigDecimal.ZERO) <= 0) {
93	                throw new CheckoutException("PEDIDO_INVALIDO");
94	            }
95	        }
96	
97	        if (request.getNivelClube() == null) {
98	            throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
99	        }
100	
101	        if (request.getRegiao() == null) {
102	            throw new CheckoutException("REGIAO_INVALIDA");
103	        }
104	
105	        if (request.getModalidadeEntrega() == null) {
106	            throw new CheckoutException("MODALIDADE_INVALIDA");
107	        }
108	    }
109	
110	    private BigDecimal calcularSubtotalProdutos(CheckoutRequest request) {
111	        BigDecimal subtotal = BigDecimal.ZERO;
112	        for (ItemCarrinho item : request.getItens()) {
113	            BigDecimal valorItem = item.getPrecoUnitario()
114	                .multiply(new BigDecimal(item.getQuantidade()));
115	            subtotal = subtotal.add(valorItem);
116	        }
117	        return arredondar(subtotal);
118	    }
119	
120	    private BigDecimal calcularPesoTotal(CheckoutRequest request) {
121	        BigDecimal pesoTotal = BigDecimal.ZERO;
122	        for (ItemCarrinho item : request.getItens()) {
123	            BigDecimal pesoItem = item.getPesoKg()
124	                .multiply(new BigDecimal(item.getQuantidade()));
125	            pesoTotal = pesoTotal.add(pesoItem);
126	        }
127	        return pesoTotal;
128	    }
129	
130	    private void validarModalidadeDisponivel(ModalidadeEntrega modalidade, BigDecimal pesoTotal) {
131	        if (modalidade.getLimitePesoKg() != null &&
132	            pesoTotal.compareTo(modalidade.getLimitePesoKg()) > 0) {
133	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
134	        }
135	    }
136	
137	    private Cupom validarCupom(String codigoCupom, BigDecimal subtotalProdutos) {
138	        if (codigoCupom == null || codigoCupom.isBlank()) {
139	            return null;
140	        }
141	
142	        try {
