            Cupom cupom = Cupom.valueOf(codigoCupom);

            if (cupom.getValorMinimoCompra().compareTo(BigDecimal.ZERO) > 0 &&
                subtotalProdutos.compareTo(cupom.getValorMinimoCompra()) < 0) {
